"""Root-reviewed translations of the remaining original table cards."""
import copy,json
from pathlib import Path
ROOT=Path(__file__).parent
cards={}
source=json.loads((ROOT/'inventory/remaining-table-cell-text.json').read_text(encoding='utf8'))
def block(english,russian,text):return {'type':'paragraph','headingEnglish':english,'headingRussian':russian,'russian':text}
def card(en,ru,blocks,category='Критическая операция (Crit Op)'):
 return {'kind':'card','titleEnglish':en,'titleRussian':ru+' ('+en+')','categoryRussian':category,'blocks':blocks,'verifiedAgainstPixels':True}
def action(en,ru,text,cost=1):return block(en+' '+str(cost)+'AP',ru+' — '+str(cost)+' AP',text)
def points(text):return block('Victory Points','Победные очки (VP)',text)
def rules(text):return block('Additional Rules','Дополнительные правила',text)
restriction='\nЭто действие нельзя выполнять в первом раунде или в дистанции контроля вражеского оперативника.'
def atlas(id,tiles):
 s=source[id];cards[id]={'kind':'atlas','columns':s['columns'],'rows':s['rows'],'tiles':{str(i):c for i,c in tiles.items()},'blankTiles':[i for i in range(s['columns']*s['rows']) if i not in tiles],'verifiedAgainstPixels':True}
crit={}
crit[0]=card('1. Secure','1. Закрепление',[action('Secure','Закрепить','Один маркер цели, контролируемый активным оперативником, закрепляется за вашим отрядом, пока вражеский отряд не закрепит его за собой.'+restriction),points('В конце каждого раунда после первого:\n• Если хотя бы один маркер цели закреплён за вашим отрядом, получите 1 VP.\n• Если за вашим отрядом закреплено больше маркеров целей, чем за отрядом противника, получите ещё 1 VP.')])
crit[1]=card('2. Loot','2. Сбор трофеев',[action('Loot','Собрать трофеи','Один маркер цели, контролируемый активным оперативником, разграблен.\nЭто действие нельзя выполнять в первом раунде, в дистанции контроля вражеского оперативника или если с этого маркера уже собирали трофеи в этом раунде.'),points('Каждый раз, когда дружественный оперативник выполняет действие «Собрать трофеи» (Loot), получите 1 VP, но не более 2 VP за раунд.')])
crit[2]=card('3. Transmission','3. Передача сигнала',[action('Initiate Transmission','Начать передачу','Один маркер цели, контролируемый активным оперативником, передаёт сигнал до начала следующего раунда.'+restriction),points('В конце каждого раунда после первого:\n• Если дружественные оперативники контролируют хотя бы один передающий сигнал маркер цели, получите 1 VP.\n• Если дружественные оперативники контролируют больше передающих сигнал маркеров целей, чем вражеские, получите ещё 1 VP.')])
crit[3]=card('4. Upload','4. Загрузка данных',[action('Upload','Загрузить данные','Удалите все очки загрузки (Upload points) противника, если они есть, с одного маркера цели, контролируемого активным оперативником.\nЗатем этот маркер получает 1 ваше очко загрузки, если он ещё не получал ваше очко загрузки в этом раунде и вы ещё не начисляли VP за него. Используйте кубик как счётчик ваших очков загрузки на маркере.'+restriction),points('В конце каждого раунда после первого вы можете начислить VP за любые маркеры целей, на которых есть хотя бы 1 ваше очко загрузки. За каждый выбранный маркер удалите с него все ваши очки загрузки и получите столько же VP. За каждый маркер можно начислить VP лишь один раз за бой. Дружественным оперативникам не требуется контролировать маркер для начисления VP.')])
crit[4]=card('5. Intel','5. Разведданные',[action('Compile Intel','Собрать разведданные','Один маркер цели, контролируемый активным оперативником, получает 1 очко разведданных (Intel point). Используйте кубик как счётчик этих очков.\nЭто действие нельзя выполнять в первом раунде, в дистанции контроля вражеского оперативника или если этот маркер уже получал очко разведданных в этом раунде.'),rules('В каждом раунде после первого действие «Поднять маркер» (Pick Up Marker) можно выполнять с маркером цели, на котором есть хотя бы 1 очко разведданных. После выполнения этого действия маркер больше не может получать очки разведданных.'),points('В конце четвёртого раунда за каждый маркер цели, контролируемый дружественными оперативниками, получите число VP, равное его очкам разведданных, то есть 0–3 VP.')])
crit[5]=card('6. Extraction','6. Эвакуация',[action('Search','Обыскать','Один маркер цели, контролируемый активным оперативником, обыскан. Если это последний ещё не обысканный маркер цели, он становится маркером цели эвакуации (extraction objective marker).\nЭто действие нельзя выполнять в первом раунде, в дистанции контроля вражеского оперативника или если этот маркер уже был обыскан.'),rules('С маркером цели эвакуации можно выполнять действие «Поднять маркер» (Pick Up Marker). Пока оперативник переносит его, ухудшите характеристику HIT его оружия на 1; оперативника нельзя убрать и снова выставить более чем в 6 дюймах от прежней позиции, и он не может выполнять действия «Атака» (Charge) или «Рывок» (Dash).'),points('Каждый раз, когда дружественный оперативник выполняет действие «Обыскать» (Search), получите 1 VP, если это первый или третий обысканный маркер цели, либо 2 VP, если это второй.\nВ конце каждого раунда после первого, если дружественные оперативники контролируют маркер цели эвакуации, получите 1 VP, а в четвёртом раунде — 2 VP вместо 1.')])
crit[6]=card('7. Sabotage','7. Саботаж',[action('Sabotage','Провести саботаж','Если активный оперативник контролирует маркер цели, целиком находящийся на территории противника, на этом маркере проведён саботаж.\nЭто действие нельзя выполнять в первом раунде, в дистанции контроля вражеского оперативника или если на этом маркере уже проводили саботаж в этом раунде.'),points('Каждый раз, когда дружественный оперативник выполняет действие «Провести саботаж» (Sabotage), получите 1 VP.\nВ конце каждого раунда после первого получите по 1 VP за каждый из следующих маркеров, контролируемых дружественными оперативниками:\n• Маркер цели целиком на вашей территории, если в этом раунде на нём не проводили саботаж.\n• Маркер цели на центральной линии.\nЗа эту операцию нельзя получить более 2 VP за раунд.')])
crit[7]=card('8. Power Surge','8. Энергетический всплеск',[action('Reroute Power','Перенаправить энергию','Один активированный всплеском маркер цели, контролируемый активным оперативником, перенаправлен.\nЭто действие нельзя выполнять в первом раунде, в дистанции контроля вражеского оперативника или если этот маркер уже был перенаправлен.'),rules('Как стратегический манёвр (Strategic Gambit) в каждом раунде после первого один игрок выбирает маркер цели, активированный всплеском до начала следующего раунда. Нельзя выбрать ранее активированный всплеском маркер. Первым выбирает игрок без инициативы; в последующих раундах игроки чередуются.'),points('Каждый раз, когда дружественный оперативник выполняет действие «Перенаправить энергию» (Reroute Power), получите 1 VP.\nВ конце каждого раунда после первого:\n• Если дружественные оперативники контролируют активированный всплеском маркер цели, получите 1 VP.\n• Если дружественные оперативники контролируют больше маркеров целей, чем вражеские, получите 1 VP.\nЗа эту операцию нельзя получить более 2 VP за раунд.')])
crit[8]=card('9. Coordinates','9. Координаты',[action('Input Coordinates','Ввести координаты','Один маркер цели, контролируемый активным оперативником, получает 1 ваше очко цели (Objective point). Используйте кубики как счётчики ваших очков цели на маркере.\nЭто действие нельзя выполнять в первом раунде, в дистанции контроля вражеского оперативника или если этот маркер уже получал ваше очко цели в этом раунде.'),points('В конце четвёртого раунда:\n• За каждый маркер цели, на котором есть хотя бы 1 ваше очко цели, получите 1 VP, либо 2 VP, если этот маркер целиком находится на территории противника.\n• За каждый маркер цели, на котором ваших очков цели больше, чем очков противника, получите ещё 1 VP.')])
atlas('f2d45d7d07d9c1e4',crit)
scouting={
0:card('1. Equip','1. Снаряжение',[rules('Выберите один дополнительный вариант снаряжения, который вы ещё не выбирали. При определении инициативы «Снаряжение» (Equip) побеждает «Приём» (Ploy).')],'Шаг разведки (Scouting Step)'),
1:card('2. Ploy','2. Приём',[rules('В первой фазе стратегии вы можете применить один стратегический приём (Strategy Ploy) за 0 CP. При определении инициативы «Приём» (Ploy) побеждает «Перемещение» (Reposition).')],'Шаг разведки (Scouting Step)'),
2:card('3. Reposition','3. Перемещение',[rules('Выполните бесплатное действие «Перемещение» (Reposition) одним дружественным оперативником, целиком находящимся в вашей зоне высадки. Он должен закончить это действие целиком в пределах 3 дюймов от вашей зоны высадки. При определении инициативы «Перемещение» (Reposition) побеждает «Снаряжение» (Equip).')],'Шаг разведки (Scouting Step)')}
atlas('cae978d9a7e65fc8',scouting)
for id,n,ordinal in [('f6a4267fb958d248',1,'первом'),('ff45a2ff5ff392c5',2,'втором'),('1d04721c13800030',3,'третьем')]:
 cards[id]=card('+'+str(n)+'/-'+str(n)+' to your initiative roll','+'+str(n)+'/-'+str(n)+' к броску инициативы',[rules('Передайте эту карту игроку, проигравшему бросок инициативы в '+ordinal+' раунде. Он может использовать её один раз в одной из последующих фаз стратегии.')],'Инициатива (Initiative)')
cards['d2e02a7e79eff3be']=card('Re-roll your initiative roll','Перебросьте инициативу',[rules('Передайте эту карту игроку, у которого не было инициативы при подготовке боя, то есть который не выбирал зоны высадки. Он может использовать её один раз в одной из последующих фаз стратегии.')],'Инициатива (Initiative)')
zeal=[
('+1 APL for Control','+1 APL при контроле','Примените эту карту рвения (Zeal) во время активации или контратаки дружественного оперативника либо в конце раунда. Выберите один маркер цели, оспариваемый дружественными оперативниками. До начала следующего раунда при определении контроля над ним считайте суммарный APL дружественных оперативников, оспаривающих его, на 1 выше, если хотя бы один дружественный оперативник оспаривает этот маркер. Нельзя применять карту, если дружественные оперативники не оспаривают ни одного маркера цели.'),
('-D3 Damage Shot','−D3 урона при стрельбе','Примените эту карту рвения (Zeal), когда враг стреляет по дружественному оперативнику и один из атакующих кубиков противника наносит урон. Игнорируйте D3 единиц этого урона.'),
('-D3 Damage Strike','−D3 урона при ударе','Примените эту карту рвения (Zeal), когда враг сражается или наносит ответные удары дружественному оперативнику и один из атакующих кубиков противника наносит урон. Игнорируйте D3 единиц этого урона.'),
('Max Success Defence','Все кубики защиты успешны','Примените эту карту рвения (Zeal), когда враг стреляет по дружественному оперативнику, на шаге броска защитных кубиков (Roll Defence Dice). Сохраните все ваши защитные кубики как обычные успехи, не бросая их.'),
('Revive onto 1 Wound','Выжить с 1 раной','Примените эту карту рвения (Zeal), когда дружественный оперативник должен быть выведен из строя. Он не выведен из строя, у него остаётся 1 рана, и до конца этого действия его нельзя вывести из строя. Сбросьте все оставшиеся атакующие кубики, включая ваши, если этот оперативник сражается или наносит ответные удары. Затем он может бесплатно выполнить «Рывок» (Dash) или «Отступление» (Fall Back); при отступлении он не может переместиться более чем на 3 дюйма. Это разрешено, даже если он уже выполнял действие, запрещающее «Рывок» или «Отступление».'),
('Free Action','Бесплатное действие','Примените эту карту рвения (Zeal) во время активации дружественного оперативника, до или после его действия. Он немедленно бесплатно выполняет одно действие стоимостью 1 AP.'),
('Ignore Weapon Rule','Отключить правило оружия','Примените эту карту рвения (Zeal), когда дружественный оперативник выбран целью стрельбы или противником в ближнем бою и противник уже выбрал оружие своего оперативника. Выберите одно правило этого оружия, кроме «Дальность X» (Range X). Оружие теряет выбранное правило до конца этой последовательности. Нельзя применять карту, если у этого оружия нет правил, которые можно выбрать.'),
('Critical Defence','Критический успех защиты','Примените эту карту рвения (Zeal), когда враг стреляет по дружественному оперативнику, на шаге броска защитных кубиков (Roll Defence Dice). Сохраните один ваш обычный успех как критический. Нельзя применять карту, если у вас нет обычных успехов.'),
('Heal 3D3','Восстановить 3D3 ран','Примените эту карту рвения (Zeal) во время активации или контратаки дружественного оперативника, до или после его действия. Он восстанавливает 3D3 потерянных ран. Нельзя применять карту, если у него нет потерянных ран.'),
('Gain 1CP','Получить 1 CP','Примените эту карту рвения (Zeal) в любой момент боя. Получите 1 CP.'),
('Double Block (Fight)','Двойной блок в ближнем бою','Примените эту карту рвения (Zeal), когда дружественный оперативник сражается или наносит ответные удары и вы блокируете успехом. Этим успехом можно заблокировать один, как обычно, или два ещё не разрешённых успеха противника. Нельзя применять карту, если у противника нет кубиков, которые можно заблокировать.'),
('Obscured','Заслонённость','Примените эту карту рвения (Zeal), когда враг выполняет «Стрельбу» (Shoot) и противник выбирает целью дружественного оперативника более чем в 6 дюймах от стрелка. До конца этого действия дружественный оперативник считается заслонённым (Obscured). Это имеет приоритет над всеми правилами, запрещающими считать его заслонённым.'),
('Free Ending Action','Бесплатное действие в конце фазы','Примените эту карту рвения (Zeal) в конце фазы перестрелки. Один дружественный оперативник немедленно бесплатно выполняет одно действие, но не может переместиться более чем на 2 дюйма. Для этого вы можете сменить его приказ.'),
('Use or Change Ploy','Применить или сменить приём','Примените эту карту рвения (Zeal) в фазе перестрелки, до или после действия оперативника. Немедленно выполните одно из следующего:\n• Примените стратегический приём (Strategy Ploy), несмотря на текущую фазу, оплатив его обычную стоимость в CP.\n• Замените стратегический приём, применённый вами в этом раунде, другим. Правила прежнего приёма больше не действуют. Если новый приём дороже, доплатите разницу в CP.\nНельзя применять карту, если ни один вариант не выполним.'),
("Reveal Opponent's Cards",'Раскрыть карты противника','Примените эту карту рвения (Zeal) во время активации или контратаки дружественного либо вражеского оперативника, до или после его действия. Противник должен раскрыть все карты на своей руке. Нельзя применять карту, если у противника нет карт на руке.'),
('Re-roll Defence Dice','Перебросить защитные кубики','Примените эту карту рвения (Zeal), когда враг стреляет по дружественному оперативнику, после броска ваших защитных кубиков. Перебросьте любые из них. Нельзя применять карту, если вы не можете перебросить ни одного защитного кубика.')]
blood=[
('+D3 Damage Shot','+D3 урона при стрельбе','Примените эту карту крови (Blood), когда дружественный оперативник стреляет, на шаге разрешения атакующих кубиков (Resolve Attack Dice), когда один из ваших атакующих кубиков наносит урон. Нанесите D3 дополнительного урона.'),
('+D3 Damage Strike','+D3 урона при ударе','Примените эту карту крови (Blood), когда дружественный оперативник сражается, на шаге разрешения атакующих кубиков (Resolve Attack Dice), когда один из ваших атакующих кубиков наносит урон. Нанесите D3 дополнительного урона.'),
('+1" Move','+1 дюйм к MOVE','Примените эту карту крови (Blood), когда дружественный оперативник выполняет «Атаку» (Charge) или «Перемещение» (Reposition). До конца этого действия увеличьте его MOVE на 1 дюйм. Это не суммируется с другими положительными изменениями его MOVE.'),
('Critical Attack','Критический успех атаки','Примените эту карту крови (Blood), когда дружественный оперативник стреляет или сражается, на шаге броска атакующих кубиков (Roll Attack Dice). Сохраните один ваш обычный успех как критический. Нельзя применять карту, если у вас нет обычных успехов.'),
('Re-roll Attack Dice','Перебросить атакующие кубики','Примените эту карту крови (Blood), когда дружественный оперативник стреляет или сражается, после броска ваших атакующих кубиков. Перебросьте любые из них. Нельзя применять карту, если вы не можете перебросить ни одного атакующего кубика.'),
('Action on Incapacitation','Действие перед гибелью','Примените эту карту крови (Blood), когда готовый дружественный оперативник выведен из строя. Перед удалением из зоны боя он может бесплатно выполнить одно действие, кроме «Ближнего боя» (Fight); для этого вы можете сменить его приказ. Затем он выведен из строя как обычно.'),
('Double Fight/Shoot','Повторить бой или стрельбу','Примените эту карту крови (Blood) во время активации или контратаки дружественного оперативника, после того как он выполнил «Ближний бой» (Fight) или «Стрельбу» (Shoot). Он немедленно выполняет то же действие снова. Это имеет приоритет над ограничениями действий. Если у оперативника есть правило фракции «Астартес» (Astartes), второе действие бесплатно.'),
('Take Initiative','Захватить инициативу','Примените эту карту крови (Blood) в начале шага инициативы (Initiative) фазы стратегии. Инициатива автоматически у вас: не проводите состязательный бросок.'),
('Max Success Attack','Все кубики атаки успешны','Примените эту карту крови (Blood), когда дружественный оперативник стреляет или сражается, на шаге броска атакующих кубиков (Roll Attack Dice). Сохраните все ваши атакующие кубики как обычные успехи, не бросая их.'),
('Free Starting Action','Бесплатное действие в начале фазы','Примените эту карту крови (Blood) в начале фазы перестрелки. Один дружественный оперативник немедленно бесплатно выполняет одно действие, но не может переместиться более чем на 2 дюйма. Для этого вы можете сменить его приказ.'),
('Cancel Block (Fight)','Отменить блок в ближнем бою','Примените эту карту крови (Blood), когда дружественный оперативник сражается и противник выбирает успех для блока. Сбросьте этот успех: блок не происходит, но противник всё равно считается разрешившим этот атакующий кубик.'),
('Shock and Stun','Шок и оглушение','Примените эту карту крови (Blood), когда дружественный оперативник стреляет или сражается, в конце шага броска атакующих кубиков (Roll Attack Dice), если вы сохранили хотя бы один критический успех. До конца этой последовательности оружие оперативника получает правила «Шок» (Shock) и «Оглушение» (Stun).'),
('Use or Reuse Ploy','Применить или повторить приём','Примените эту карту крови (Blood) в фазе перестрелки. Немедленно выполните одно из следующего:\n• Примените приём перестрелки (Firefight Ploy) со скидкой 1 CP, до минимума 0 CP.\n• Примените приём перестрелки во второй раз в этом раунде. Это имеет приоритет над ограничением «раз за раунд»; оплатите его обычную стоимость в CP.\nНельзя применять карту, если ни один вариант не выполним.'),
('Steal Card','Украсть карту','Примените эту карту крови (Blood) во время активации или контратаки дружественного оперативника, до или после его действия. Возьмите одну карту из руки противника. Нельзя применять карту, если у противника нет карт на руке.'),
('Prevent Mission Action','Помешать действию миссии','Примените эту карту крови (Blood), когда вражеский оперативник выполняет действие миссии на маркере цели, оспариваемом дружественными оперативниками. Противник должен потратить ещё 1 AP на это действие; если он этого не делает, уже потраченные AP не возвращаются.\nДо начала следующего раунда, пока дружественные оперативники оспаривают этот маркер, противник должен тратить ещё 1 AP на действия миссии вражескими оперативниками на нём.\nЭто не суммируется с другими правилами, требующими дополнительные AP для действий миссии.'),
('Return Discarded Card','Вернуть сброшенную карту','Примените эту карту крови (Blood) во время активации или контратаки дружественного оперативника, до или после его действия. Замешайте одну из сброшенных карт противника обратно в её колоду. Нельзя применять карту, если у противника нет сброшенных карт.')]
for id,items,category in [('43117b29791bbb9e',zeal,'Карта рвения (Zeal) · Blood and Zeal'),('25a034b953e80af9',blood,'Карта крови (Blood) · Blood and Zeal')]:
 atlas(id,{i:card(en,ru,[rules(text)],category) for i,(en,ru,text) in enumerate(items)})
typhon=[
('Spore Miasma','Споровая завеса','Густая взвесь микроскопических спор тиранидов заполняет зону боя, скрывая затаившихся врагов.','Когда оперативник стреляет по оперативнику более чем в 8 дюймах от него, бросьте один дополнительный защитный кубик.'),
('Sentient Barbs','Живые шипы','Ядовитые шипы вырастают из органических наростов и тянутся к незваным гостям, чуя новые источники биоматерии.','Когда оперативник игрока перемещается в пределах 1 дюйма от элемента террейна «Заражение тиранидов» (Tyranid Infestation), бросьте D6: на 3+ нанесите ему 1 урон. За каждую активацию бросайте только один раз для каждого элемента террейна.'),
('Birthing Sac','Родильный мешок','Сквозь слои мембран наружу пробиваются новые агрессивные биоформы, рождённые защищать наросты ксеносов.','Выставьте одного готового неигрового оперативника (NPO) с приказом «Скрытность» (Conceal) как можно ближе к случайно выбранному элементу террейна «Гестационный мешок» (Gestation Sac, S).\nЕсли это невозможно, например достигнут лимит NPO, вытяните другую карту события.'),
('Voracious','Ненасытность','Хищные биоформы повинуются повелению пожрать свою добычу.','Оружие неигровых оперативников (NPO) получает правило «Смертоносное 5+» (Lethal 5+).'),
('Ripper Swarm','Рой пожирателей','Клубок ненасытных змеевидных тварей обрушивается на ничего не подозревающую добычу, чтобы поглотить её биомассу.','Если в зоне боя нет NPO «Рой пожирателей» (Ripper Swarm), выставьте одного готового с приказом «Скрытность» (Conceal) в допустимом месте: в Joint Ops — целиком на территории NPO; в Adversary Ops — в дистанции контроля случайного маркера цели. Если возможно, также разместите его в дистанции контроля оперативника игрока.\nЕсли в зоне боя уже есть раненый NPO «Рой пожирателей», он восстанавливает все потерянные раны.\nЕсли ни один вариант не выполним, вытяните другую карту события.'),
('Feed','Пожирание','Синаптический приказ разжигает голод подвижных защитников наростов и гонит их пожирать всё на пути.','D3 неигровых оперативников (NPO) немедленно бесплатно выполняют «Ближний бой» (Fight). Если ни один не может этого сделать, вытяните другую карту события.'),
('Overrun','Натиск','Синаптическое повеление Разума Улья бросает тиранидские биоформы на добычу в неудержимом приступе агрессии.','Каждый неигровой оперативник (NPO) немедленно бесплатно выполняет «Атаку» (Charge) на расстояние до 3 дюймов; для этого можно сменить его приказ. Каждый NPO, который не может этого сделать, вместо этого может немедленно бесплатно выполнить «Рывок» (Dash).'),
('Lurk','Затаиться','Ксеносы инстинктивно уходят от обнаружения и прячутся в тенях, ожидая удобного момента для удара.','Когда оперативник игрока стреляет по NPO, перебросьте один защитный кубик NPO, если это ему выгодно.\nКогда игрок должен нанести удар (Strike) по NPO, бросьте D6: на 5+ он должен вместо этого выполнить блок (Block). Если блок невозможен, например успех обычный, а у NPO остались только критические успехи, удар не имеет эффекта.'),
('Synaptic Backlash','Синаптический откат','Треск нейронных помех пронзает мозг тех, кто осмелился бросить вызов воле Разума Улья.','Выберите одного оперативника игрока и бросьте D6:\n• Если результат выше его APL, уменьшите его APL на 1.\n• Если результат равен его APL или ниже, выберите другого оперативника игрока и повторите процесс.\nЭто не действует на оперативников игроков, которые препятствуют любым психическим правилам (PSYCHIC), например психическим действиям.')]
typhon.append(typhon[2])
def events(id,items,category):
 tiles={}
 for i,(en,ru,flavor,text) in enumerate(items):
  c=card(en,ru,[rules(text)],category);c['flavorRussian']=flavor;tiles[i]=c
 atlas(id,tiles)
events('c45cc9ffe62c7cc7',typhon,'Карта события (Event Card) · Typhon')
spawn_scarab='Если в зоне боя нет NPO «Рой каноптековых скарабеев» (Canoptek Scarab Swarm), выставьте одного готового с приказом «Скрытность» (Conceal) в допустимом месте:\n• В Joint Ops — с точкой доступа случайного люка (Hatchway Access Point) в его дистанции контроля и целиком на территории NPO.\n• В Adversary Ops — со случайным маркером цели в его дистанции контроля.\nЕсли это невозможно, выставьте его как можно ближе. Если возможно, разместите его в дистанции контроля оперативника игрока.\nЕсли в зоне боя уже есть раненый NPO «Рой каноптековых скарабеев», он восстанавливает все потерянные раны.\nЕсли ни один вариант не выполним, вытяните другую карту события.'
awakened=('Awakened Warrior','Пробудившийся воин','Спящие воины, лишённые собственных стазисных склепов, стоят вдоль проходов гробницы, готовые пробудиться и стать безмолвными палачами.','Выставьте готового NPO «Воин-некрон» (Necron Warrior) с приказом «Скрытность» (Conceal) так, чтобы в его дистанции контроля был элемент террейна со встроенной моделью воина-некрона: торец стены или соответствующая сторона A2.\nЕсли это невозможно, например достигнут лимит NPO, вытяните другую карту события.')
tomb=[
('Dark of the Tomb','Мрак гробницы','Могильный сумрак внезапно сгущается. Неестественная тьма застилает зрение и приборы, словно сама смерть подступает ближе.','Когда оперативник игрока стреляет по оперативнику более чем в 8 дюймах от него, атакующие кубики нельзя перебрасывать.'),
('The Maze Reforms','Лабиринт меняется','По проходам пробегает древняя энергия. Открытые порталы запечатываются, разрывы стен затягиваются: протоколы гробницы отсекают пути отхода захватчиков.','Закройте одну случайную открытую точку пролома (Breach Point) и D3 случайных открытых люка (Hatchway). Это имеет приоритет над обычными правилами точек пролома.\nЕсли ни одну точку или люк нельзя закрыть, вытяните другую карту события.'),
awakened,
('Stirrings of Horror','Пробуждение ужаса','Присутствие захватчиков потревожило повреждённое сознание главной программы. Зловещий разум направляет больше энергии ближайшим стражам.','Увеличьте текущий уровень угрозы (Threat Level) на 1. Если он уже равен 15 или вы играете в Adversary Ops, вместо этого выставьте ещё одного NPO в качестве подкрепления в этой фазе стратегии.'),
('A Chittering Drone','Стрекочущий гул','Шорох щёлкающих челюстей предвещает появление роя конструкций.',spawn_scarab),
('My Will Be Done','Да исполнится моя воля','Даже во сне высокомерные некронские вельможи способны навязывать подданным свою волю.','Когда NPO находится в той же комнате, что и элемент террейна «Саркофаг» (Sarcophagus, C1), его оружие получает правило «Точное 1» (Accurate 1).'),
('Living Metal Flux','Всплеск живого металла','Полуразумный металл тел стражей стремительно перестраивается, затягивая самые тяжёлые повреждения.','Все NPO немедленно восстанавливают до D3+2 потерянных ран. Бросайте отдельно за каждого.\nЕсли ни один NPO не может восстановить раны, вытяните другую карту события.'),
('Countertemporal Shifting','Временное смещение','Системы, искажающие причинность, оживают. Тела слуг гробницы мерцают в соседних временных линиях, ускользая от тяжёлых ударов.','Каждый раз, когда атакующий кубик наносит NPO 3 урона или больше, бросьте D6: на 5+ уменьшите этот нанесённый урон на 1.'),
awakened,
('Reanimation Protocols','Протоколы реанимации','Призрачные сигналы запускают системы гробницы, снова и снова возвращающие некронов с грани уничтожения.','Когда каждый NPO впервые в этом раунде должен быть выведен из строя, бросьте D6: на 4+ он вместо этого реанимирован (Reanimated). При реанимации:\n• У него остаётся 1 рана, и до конца действия его нельзя вывести из строя.\n• Сбросьте все оставшиеся атакующие кубики, включая ваши, если этот NPO сражается или наносит ответные удары.\n• Если NPO был готовым (Ready), сделайте его использованным (Expended).\n• Уменьшите его APL на 1 до конца следующей активации.'),
('Transdimensional Relocation','Межпространственное перемещение','Защитные системы гробницы расплетают и заново ткут реальность, рассеивая захватчиков по тёмным закоулкам.','Случайно выберите двух оперативников игроков; в Adversary Ops — одну пару из каждого отряда. Уберите обоих из зоны боя и выставьте каждого на прежнее место другого: поменяйте их позициями.\nПовторите этот процесс ещё два раза, если возможно.\nЕсли в зоне боя у какого-либо отряда есть только один оперативник игрока, вытяните другую карту события.'),
('Subjugation Glyphs','Глифы подчинения','Призрачная энергия складывается в древние знаки на стенах. Волны устрашающего превосходства хозяев склепа подтачивают волю незваных гостей.','Случайно выберите одного оперативника игрока и бросьте D6:\n• Если результат выше его APL, уменьшите его APL на 1.\n• Если результат равен его APL или ниже, случайно выберите другого оперативника игрока и повторите процесс. В Adversary Ops следующий случайный выбор делается противником среди его оперативников; игроки чередуются, пока APL одного оперативника не уменьшится или бросок не будет сделан за всех оперативников игроков.'),
('Enforcer of the Phaerons','Исполнитель воли фаэронов','Королевские стражи обладают инициативой, недоступной низшим некронам. Они проводят волю правителей, направляя подчинённых с убийственной точностью.','Когда NPO находится в той же комнате, что и NPO «Королевский страж» (Royal Warden), его оружие получает правило «Непрерывное» (Ceaseless).\nЕсли в зоне боя нет NPO «Королевский страж», вытяните другую карту события.'),
('Flesh Hunger','Жажда плоти','Свежие жертвы манят Свежевателей, как запах крови манит хищника. Они вырываются из тёмных ниш и пространственных разрывов, бросаясь на добычу.','Если в зоне боя нет NPO «Свежеватель» (Flayed One), выставьте одного готового с приказом «Скрытность» (Conceal) в допустимом месте:\n• В Joint Ops — с точкой доступа случайного люка в его дистанции контроля и целиком на территории NPO.\n• В Adversary Ops — со случайным маркером цели в его дистанции контроля.\nЕсли это невозможно, выставьте его как можно ближе. Если возможно, разместите его в дистанции контроля оперативника игрока.\nЕсли в зоне боя уже есть один или несколько NPO «Свежеватель», выберите одного: он немедленно бесплатно выполняет «Атаку» (Charge) или «Перемещение» (Reposition) к ближайшему оперативнику игрока.\nЕсли ни один вариант не выполним, вытяните другую карту события.'),
('Rewards of Annihilation','Награда за уничтожение','Каждое убийство пробуждает в разрушителе остатки мрачного удовлетворения и запускает скрытые резервы энергии, позволяя продолжать бойню.','Когда NPO «Скорпех-разрушитель» (Skorpekh Destroyer) или «Хексмарк-разрушитель» (Hexmark Destroyer) выводит из строя оперативника игрока, этот NPO восстанавливает до D3 потерянных ран; если характеристика WOUNDS жертвы была 12 или больше, вместо этого — до 2D3 потерянных ран.')]
events('ddbda0e2ab98ed4a',tomb,'Карта события (Event Card) · Мир-гробница (Tomb World)')
existing=json.loads((ROOT/'ru-images-missions.json').read_text(encoding='utf8'))
def reveal(text):return block('Reveal','Раскрытие',text)
def tac(en,ru,blocks,archetype):return card(en,ru,blocks,'Многопользовательская тактическая задача (Multiplayer Tac Op) · '+archetype)
mp={}
mp[0]=tac('Rout','Разгром',[reveal('Когда впервые получаете VP за эту задачу.'),points('Каждый раз, когда дружественный оперативник выводит из строя вражеского оперативника, если этот дружественный оперативник находится в пределах 8 дюймов от зоны высадки противника, получите 1 VP. Если это условие выполнено и характеристика WOUNDS жертвы была 12 или больше, вместо этого получите 2 VP.\nЗа эту задачу нельзя получить более 2 VP за раунд.')],'Найти и уничтожить (Seek & Destroy)')
mp[1]=tac('Dominate','Господство',[reveal('Когда дружественный оперативник впервые выводит из строя вражеского оперативника.'),rules('Каждый раз, когда дружественный оперативник выводит из строя вражеского оперативника, этот дружественный оперативник получает один ваш жетон господства (Dominate).'),points('В конце третьего и четвёртого раундов можно снять жетоны господства с дружественных оперативников, которые не выведены из строя. За каждый снятый жетон получите 1 VP.\nЗа эту задачу нельзя получить более 3 VP за раунд.')],'Найти и уничтожить (Seek & Destroy)')
mp[2]=tac('Sweep & Clear','Зачистка',[reveal('Когда враг впервые выведен из строя, оспаривая маркер цели, либо когда дружественный оперативник впервые выполняет действие «Зачистить» (Clear) — что наступит раньше.'),rules('Когда враг, оспаривающий маркер цели, выведен из строя, этот маркер получает один ваш жетон «Прочёсано» (Swept), если такого жетона на нём ещё нет. Жетон остаётся до шага подготовки (Ready) следующей фазы стратегии.'),action('Clear','Зачистить','Маркер цели, контролируемый активным оперативником, зачищен до конца раунда.'+restriction),points('В конце каждого раунда после первого, если дружественные оперативники контролируют хотя бы один маркер цели с вашим жетоном «Прочёсано», получите 1 VP. Если это условие выполнено и хотя бы один из этих маркеров также зачищен, вместо этого получите 2 VP.\nЗа эту задачу нельзя получить более 2 VP за раунд.')],'Найти и уничтожить (Seek & Destroy)')
