def illustration(id,box,caption,height=260,overlays=None):
 return {'type':'figure','sourceimageid':id,'sourceBox':box,'illustrationOnly':True,'captionRussian':caption,'maxHeight':height,'labelOverlays':overlays or []}
cards['0766d946b2f983e2']=card('Killzone: Nightmare','Зона боя «Кошмар»',[
 block('Killzone: Nightmare','Кошмар (Nightmare)','Дополнение к зоне боя «Бета-Децима» (Bheta-Decima). Здесь возвышается генераторный узел (Generatorum Hub), существенно влияющий на бой. Это крупный детализированный элемент террейна; правила его частей приведены отдельно.'),
 block('Generatorum Hub','Генераторный узел','Все части этого элемента террейна имеют особенность «Тяжёлый» (Heavy). У него два уровня; второй выделен жёлтым. Оба уровня имеют особенность «Высота» (Vantage Point).\nДистанция взаимодействия (Engagement Range) между оперативниками, находящимися на высотах этого элемента террейна, определяется по горизонтали.'),
 illustration('0766d946b2f983e2',[.04,.265,.98,.66],'Жёлтые контуры: второй уровень и высоты генераторного узла.',230),
 {'type':'column-break'},
 block('First Level','Первый уровень','Первый уровень и небольшие выступающие края, выделенные зелёным, считаются одной поверхностью: игнорируйте небольшую разницу высот. Оперативников можно размещать на этих краях, но нельзя использовать их как укрытие (Cover).'),
 illustration('0766d946b2f983e2',[.03,.686,.65,.95],'Зелёная область: первый уровень и выступающие края.',140)],'Правила террейна · версия исходного дополнения')
cards['6566df6428416efe']=card('Generatorum Hub: Climbing, Dropping and Sides','Генераторный узел: подъём, спуск и стороны',[
 block('Climbing and Dropping','Подъём и спуск','Чтобы подняться на каждый уровень, оперативник проходит 2 дюйма по вертикали (круг ○ в оригинале).\nПри спуске на один уровень высота меньше 2 дюймов, поэтому её игнорируют. При спуске на два уровня, с верхнего на пол зоны боя, оперативник проходит 2 дюйма по вертикали.\nОперативников нельзя выставлять на ступенях или заканчивать на них перемещение. Однако вертикальное расстояние, пройденное по ступеням, игнорируется.'),
 illustration('6566df6428416efe',[.1,.02,.385,.229],'Ступени (Steps).',150),
 {'type':'column-break'},
 block('Sides','Боковые стороны','Чтобы быстрее и единообразно определять укрытие у детализированных боковых сторон, используйте следующее правило. Оперативники на полу зоны боя могут получать укрытие от округлённых углов, рисунок 1. Части между округлёнными углами — небольшие выступы по бокам, рисунок 2 — укрытия не дают.'),
 illustration('6566df6428416efe',[.36,.676,.67,.96],'Рисунок 1: цель в укрытии.',170,[{'box':[.025,.03,.43,.22],'russian':'1. Цель в укрытии'}]),
 illustration('6566df6428416efe',[.69,.676,.96,.96],'Рисунок 2: цель без укрытия.',170,[{'box':[.025,.03,.45,.22],'russian':'2. Цель без укрытия'}])], 'Правила террейна · версия исходного дополнения')
cards['69c784a6fab93df8']=card('Descent Killzone Rules','Правила многоуровневой зоны боя',[
 block('Entryway Markers','Маркеры перехода (Entryway)','Оба уровня используют парные маркеры перехода с одинаковыми номерами: 1, 2 и 3.'),
 block('Climbing Entryway Markers','Перемещение через переход','Если маркер перехода находится в дистанции контроля дружественного оперативника, за 3 дюйма перемещения он может подняться по нему. Уберите оперативника из зоны боя и снова выставьте в допустимом месте так, чтобы одноимённый маркер в другой зоне боя находился в его дистанции контроля; если это невозможно — как можно ближе к нему. Его нельзя выставить в дистанции контроля врага, если выполняемое действие не разрешает это, как, например, «Атака» (Charge).\nПосле выставления можно продолжать движение, если осталась дистанция и действие это разрешает. При проверке ограничений расстояния на повторное выставление, например для переносчика реликвии в миссии Adversary Ops 3 «Пробуждение» (Awakening), такой переход считается перемещением на 3 дюйма.'),
 block('Shooting from Entryway Markers','Стрельба через переход','Когда дружественный оперативник выполняет «Стрельбу» (Shoot), если маркер перехода находится в его дистанции контроля, вместо обычного выбора допустимой цели можно выбрать врага, в чьей дистанции контроля находится маркер с тем же номером в другой зоне боя. Игнорируйте правило оружия «Дальность X» (Range X). На эту последовательность цель не может получать укрытие (Cover) или заслонение (Obscured). По-прежнему нельзя выбирать врага, в чьей дистанции контроля находятся дружественные оперативники.\nЕсли цель находится в зоне боя с правилами тесного боя (Close Quarters), например Галлоударк (Gallowdark), применяйте дополнительное правило «Плотная среда» (Condensed Environment), даже если стреляющий оперативник находится в другой зоне боя.'),
 block('Relocation Rules','Правила повторного выставления','Некоторые правила фракций убирают оперативника и снова выставляют его, например «Полёт» (FLY) или «Путь теней» (SHADOW PASSAGE) Мандрейков (MANDRAKE). В многоуровневой зоне боя они не позволяют выставить оперативника на другом уровне: применять их можно внутри верхней или нижней зоны, но нельзя переходить между ними.'),
 block('Faction Markers','Маркеры отрядов','Маркеры десантирования (Drop) «Темпестус Аквилон» (TEMPESTUS AQUILON) и туннелей (Tunnel) Равенеров (RAVENER) нельзя размещать в разных зонах боя: выберите верхнюю либо нижнюю. В миссии Adversary Ops 1 «В глубины» (Into the Depths) маркеры в нижней зоне размещать нельзя.\nУ «Круга каноптеков» (CANOPTEK CIRCLE) учитывайте, где размещаете маркеры обелисков-узлов (OBELISK NODE) и где это разрешает карта миссии: матрицу обелисков-узлов (OBELISK NODE MATRIX) можно создавать только с маркерами в той же зоне боя.'),
 block('Guard','Охрана','Если оперативник на охране (On Guard) телепортируется в другую зону боя через телепортационную площадку, страница 57 книги, он перестаёт находиться на охране.')], 'Правила зоны боя (Killzone Rules)')
